+    }
+
+    @Test
+    void filterBarStartsEmpty() {
+        assertEquals("", nameField().getValue());
+        assertEquals("", statusField().getValue());
+        nameField().assertPlaceholder("Filter by name");
+        assertEquals("500", grid().getTotalRowCount() + "");
+        assertEquals("Showing 500 of 500", summary().textContent());
+    }
+
+    @Test
+    void nameFilterMatchesEitherFieldForEveryTerm() {
+        setNameFilter("ada aal");
