+        assertEquals(2, grid().getTotalRowCount());
+
+        setNameFilter("ada virtanen");
+        grid().waitForGridToStopLoading();
+        assertEquals(0, grid().getTotalRowCount());
+        assertEquals("Showing 0 of 500", summary().textContent());
+    }
+
+    @Test
+    void nameFilterIgnoresCaseAndAccents() {
