+        grid().waitForGridToStopLoading();
+        assertEquals(15, grid().getTotalRowCount());
+
+        setNameFilter("mäkinen");
+        grid().waitForGridToStopLoading();
+        assertEquals(15, grid().getTotalRowCount());
+
+        setNameFilter("josephine");
+        grid().waitForGridToStopLoading();
+        assertEquals(12, grid().getTotalRowCount());
+    }
+
+    @Test
+    void statusFilterNarrowsAndCombinesWithName() {
