+        assertEquals(167, grid().getTotalRowCount());
+
+        setNameFilter("makinen");
+        grid().waitForGridToStopLoading();
+        assertEquals(5, grid().getTotalRowCount());
+    }
+
+    @Test
+    void addressBarReflectsFilterWithoutPushingHistoryPerKeystroke() {
+        setNameFilter("vir");
+        grid().waitForGridToStopLoading();
+        statusField().selectItem("ACTIVE");
+        statusField().selectItem("CLOSED");
+        page.waitForTimeout(200);
+        grid().waitForGridToStopLoading();
+
+        String url = page.url();
+        assertTrue(url.contains("name=vir"), "URL should carry the name filter: " + url);
+        assertTrue(url.contains("status=ACTIVE%2CCLOSED") || url.contains("status=ACTIVE,CLOSED"),
+                "URL should carry the status filter in declaration order: " + url);
+
+        page.goBack();
+        // A single filter session must not have produced more than one extra
+        // history entry (the page load itself).
+        assertTrue(!page.url().contains("name=vir") || page.url().equals(url),
+                "Typing must not push a history entry per keystroke");
+    }
+
+    @Test
+    void openingUrlWithParametersAppliesAndDisplaysFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction("() => window.Vaadin && window.Vaadin.Flow");
+        grid().waitForGridToStopLoading();
+
+        assertEquals("vir", nameField().getValue());
+        assertEquals(10, grid().getTotalRowCount());
+        assertEquals("Showing 10 of 500", summary().textContent());
+    }
+
+    @Test
+    void typingNineLettersCostsAtMostTwoQueries() {
+        nameField().click();
+        page.locator("vaadin-text-field input").pressSequentially("aaltonenx");
+        page.waitForTimeout(600);
+        grid().waitForGridToStopLoading();
+
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing should debounce, not query once per keystroke: "
+                        + queryLog.pageQueries().size() + " page queries");
+        assertTrue(queryLog.countQueries().size() <= 2,
+                "Typing should debounce, not query once per keystroke: "
+                        + queryLog.countQueries().size() + " count queries");
+    }
+}
